$practiceSql=fcc_j90_schema()?"CASE WHEN learning_mode IS NOT NULL THEN learning_mode='practice' ELSE completion_mode='quick' OR result_type='training' END":"completion_mode='quick' OR result_type='training'";
$metrics=fcc_partner_one("SELECT COUNT(*) completed,COUNT(DISTINCT recorded_by_user_id) people,COALESCE(SUM(difficulty='hard'),0) hard,COALESCE(SUM($practiceSql),0) practice FROM forever_business_daily_outcomes WHERE status='done' AND action_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)");
$ai=fcc_partner_one("SELECT COUNT(*) total,COUNT(DISTINCT user_id) people,COALESCE(SUM(status='failed'),0) failed,COALESCE(SUM(helpful=1),0) helpful,COALESCE(SUM(helpful=0),0) unhelpful FROM fcc_partner_journey_coach WHERE created_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY");
$usage=fcc_partner_one("SELECT COALESCE(SUM(JSON_EXTRACT(usage_json,'$.input_tokens')),0) input_tokens,COALESCE(SUM(JSON_EXTRACT(usage_json,'$.output_tokens')),0) output_tokens FROM fcc_partner_journey_coach WHERE created_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY");
$events=fcc_partner_rows("SELECT event_type,COUNT(*) n,COUNT(DISTINCT user_id) people FROM fcc_partner_journey_events WHERE created_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY GROUP BY event_type");
$participants=fcc_partner_rows("SELECT u.user_id,u.name,MAX(o.action_date) last_step,COUNT(o.outcome_id) steps,COALESCE(SUM(o.difficulty='hard'),0) hard FROM users u JOIN forever_business_daily_outcomes o ON o.recorded_by_user_id=u.user_id AND o.status='done' WHERE u.status=1 GROUP BY u.user_id,u.name ORDER BY last_step DESC LIMIT 30");
$difficult=fcc_partner_rows("SELECT action_key,COUNT(*) attempts,SUM(difficulty='hard') hard FROM forever_business_daily_outcomes WHERE status='done' AND action_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY action_key ORDER BY hard DESC LIMIT 10");
